-- Fakt kartochkalari orqa tomonining ruscha matni — 59-partiya:
-- Abul Mu'in an-Nasafiy, Ahmad Yassaviy, Ajiniyoz.

UPDATE fact_cards SET detail_ru = 'Арабский учёный Хайриддин аз-Зирикли в сочинении «Аль-Аълом» и Умар Риза Каххола в сочинении «Муджам аль-муаллифин» упоминают, что учёный родился в 1027 году в городе Насаф (нынешний Карши). Источник: УзА (uza.uz).' WHERE id = 2108;
UPDATE fact_cards SET detail_ru = 'По статье УзА, учёный вырос в просвещённой семье, зрелой в науке и познании. Его дальний предок Махуль Насафи был учеником имама Мотуриди, положившего начало учению мотуридия. Источник: УзА (uza.uz).' WHERE id = 2109;
UPDATE fact_cards SET detail_ru = 'В статье УзА учёный назван одним из великих представителей науки калама: он внёс большой вклад в широкое распространение в мире учения мотуридия, основанного Абу Мансуром Мотуриди. Источник: УзА (uza.uz).' WHERE id = 2110;
UPDATE fact_cards SET detail_ru = 'Полное название сочинения — «Табсират аль-адилла фи усул ад-дин ала тарикати Аби Мансур аль-Мотуриди». Оно считается одним из весьма примечательных сочинений, хранящихся в мировых библиотеках. Источник: УзА (uza.uz).' WHERE id = 2111;
UPDATE fact_cards SET detail_ru = 'По статье УзА, среди его сочинений, хранящихся в мировых библиотеках, особенно примечательны книги «Табсират аль-адилла фи усул ад-дин», «Бахр уль-калам фи ильм иль-калам» и «Ат-тамхид ли кавоид ит-таухид». Сочинение «Бахр уль-калам» — один из основных источников школы мотуридия по науке калама. Источник: УзА (uza.uz).' WHERE id = 2112;
UPDATE fact_cards SET detail_ru = 'О его кончине в большинстве источников указан 1114 год. Мавзолей Абуль Муина ан-Насафи в селении Ковчин Каршинского района считается одним из древних мест паломничества и в наши дни благоустроен. Источник: УзА (uza.uz).' WHERE id = 2113;

UPDATE fact_cards SET detail_ru = 'Ахмад Яссави родился в городе Сайрам близ Яссы, примерно во второй половине XI века. Его отец шейх Ибрагим был из влиятельных людей, принадлежавших пути джаванмардов, а мать Айша-хатун была дочерью шейха Мусы. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1952;
UPDATE fact_cards SET detail_ru = 'Его мать Айша-хатун умерла рано, а в семь лет он лишился и отца. Воспитанием юного Ахмада занималась его сестра Гавхар Шахноз, и вместе они переселились в город Яссы. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1953;
UPDATE fact_cards SET detail_ru = 'Первым его наставником был Арслан-баб — Яссави встретился с ним в семь лет и учился у него. Позже он отправился в Бухару и стал учеником шейха Юсуфа Хамадани; там он учился вместе с Ходжой Абдулхаликом Гиждувани, Абдуллахом Барки и Ходжой Хасаном Андаки. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1954;
UPDATE fact_cards SET detail_ru = 'Вернувшись из Бухары в Яссы, Яссави прославился как наставник, положивший начало новому пути. Он стремился ещё шире привлечь тюркские народы к исламу. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1955;
UPDATE fact_cards SET detail_ru = 'Сам Яссави не создавал книги под названием «Диван мудрости» — это редкое сочинение составили его ученики и последователи. В диване искренне и трогательно раскрыты божественная любовь и состояние влюблённого, познание и блаженство постигшего; в него вошли и образцы творчества его последователей. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1956;
UPDATE fact_cards SET detail_ru = 'В источнике отмечено, что Яссави пользовался и поэзией, чтобы ещё шире привлечь тюркские народы к исламу и глубже внедрить суфийские мысли в сердце народа. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1957;
UPDATE fact_cards SET detail_ru = 'В шестьдесят три года Яссави удалился в подземную келью и предался суровому подвижничеству и молитве. Об этом он написал в своей мудрости: «В шестьдесят три я ушёл под землю». Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1958;
UPDATE fact_cards SET detail_ru = 'Большинство исследователей относит кончину Яссави к 1166–1167 годам. Он погребён в древнем городе Яссы, ставшем свидетелем совершенства «Султана познавших»; сегодня там находится университет имени Яссави. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1959;

UPDATE fact_cards SET detail_ru = 'Аджинияз родился в 1824 году в Муйнакском районе. Он один из крупных представителей каракалпакской поэзии XIX века. Источник: Ziyouz.com, раздел «Каракалпакская поэзия».' WHERE id = 2014;
UPDATE fact_cards SET detail_ru = 'Полное имя поэта — Аджинияз, сын Кусибая. Его отца звали Кусибай. Источник: Ziyouz.com, раздел «Каракалпакская поэзия».' WHERE id = 2015;
UPDATE fact_cards SET detail_ru = 'В своих стихах Аджинияз называет себя «Зевар»: доказательство тому строки «У каракалпаков есть скромный Зевар», «Бедный Зевар плачет каждый день». Источник: Ziyouz.com, раздел «Каракалпакская поэзия».' WHERE id = 2016;
UPDATE fact_cards SET detail_ru = 'Стихи «Есть у меня народ» и «Станет» приведены на портале Ziyouz.com; стихотворение «Станет» перевёл с каракалпакского Рустам Мусурмон. «Избранные сочинения» поэта издавались на каракалпакском языке в 1960, 1965, 1975, 1988 и 1994 годах. Источник: Ziyouz.com, раздел «Каракалпакская поэзия».' WHERE id = 2017;
UPDATE fact_cards SET detail_ru = 'На портале Ziyouz.com Аджинияз назван «поэтом каракалпакского народа». Его избранные сочинения не раз издавались на каракалпакском языке. Источник: Ziyouz.com, раздел «Каракалпакская поэзия».' WHERE id = 2018;
UPDATE fact_cards SET detail_ru = 'Аджинияз умер в 1878 году. Его поэтическое наследие входит в золотой фонд каракалпакской словесности. Источник: Ziyouz.com, раздел «Каракалпакская поэзия».' WHERE id = 2019;
